import * as THREE from 'three/webgpu';
import { texture, uv, vec3, vec4, float, uniform, mix, smoothstep, step, positionLocal } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-collection-badge';

  const width = 1.1;
  const height = 0.32;
  const geometry = new THREE.PlaneGeometry(width, height, 1, 1);

  const colors = (config.visual && config.visual.colors) || {
    ink: '#16161d', paper: '#e8ecf2', accent: '#ff2a38', surface: '#0b0b10'
  };

  const inkColor = new THREE.Color(colors.ink);
  const accentColor = new THREE.Color(colors.accent);
  const paperColor = new THREE.Color(colors.paper);

  let map = null;
  const imageUrl = config.assets && config.assets.imageUrl;
  if (imageUrl && ctx.textureLoader) {
    map = ctx.textureLoader.load(imageUrl);
    map.colorSpace = THREE.SRGBColorSpace;
    map.wrapS = THREE.ClampToEdgeWrapping;
    map.wrapT = THREE.ClampToEdgeWrapping;
  }

  const material = new THREE.MeshBasicNodeMaterial();
  material.transparent = true;

  const uvNode = uv();
  const grainTex = map ? texture(map, uvNode) : vec4(1, 1, 1, 1);

  const baseColor = vec3(inkColor.r, inkColor.g, inkColor.b);
  const accentVec = vec3(accentColor.r, accentColor.g, accentColor.b);

  // capsule edge light: brighten near left/right edges (x near 0 or 1)
  const edgeDist = uvNode.x.sub(0.5).abs().mul(2.0);
  const edgeGlow = smoothstep(0.82, 1.0, edgeDist);

  const hoverAmount = uniform(0.0);
  const pressAmount = uniform(0.0);

  const grainMixed = baseColor.mul(grainTex.rgb).mul(0.9).add(baseColor.mul(0.1));
  const withEdge = mix(grainMixed, accentVec, edgeGlow.mul(0.9));
  const withHover = mix(withEdge, mix(withEdge, vec3(paperColor.r, paperColor.g, paperColor.b), 0.08), hoverAmount);
  const finalColor = mix(withHover, withHover.mul(0.85), pressAmount);

  material.colorNode = vec4(finalColor, 1.0);

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'hub-collection-badge-mesh';
  group.add(mesh);

  const scenePos = (config.scenePlacement && config.scenePlacement.position) || [0, 1.6, 0];
  const sceneRot = (config.scenePlacement && config.scenePlacement.rotation) || [0, 0, 0];
  const sceneScale = (config.scenePlacement && config.scenePlacement.scale) || [1, 1, 1];

  group.position.set(scenePos[0], scenePos[1], scenePos[2]);
  group.rotation.set(sceneRot[0], sceneRot[1], sceneRot[2]);
  group.scale.set(sceneScale[0], sceneScale[1], sceneScale[2]);

  const baseY = group.position.y;
  let hoverTween = null;
  let pressTween = null;

  const onHoverIn = () => {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.timeline()
      .to(group.position, { y: baseY + 0.15, duration: 0.7, ease: 'power3.out' }, 0)
      .to(hoverAmount, { value: 1.0, duration: 0.7, ease: 'power3.out' }, 0);
  };

  const onHoverOut = () => {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.timeline()
      .to(group.position, { y: baseY, duration: 0.7, ease: 'power3.out' }, 0)
      .to(hoverAmount, { value: 0.0, duration: 0.7, ease: 'power3.out' }, 0);
  };

  const onClick = () => {
    if (pressTween) pressTween.kill();
    pressTween = gsap.timeline()
      .to(group.scale, { x: sceneScale[0] * 0.97, y: sceneScale[1] * 0.97, z: sceneScale[2] * 0.97, duration: 0.12, ease: 'back.out' }, 0)
      .to(pressAmount, { value: 1.0, duration: 0.12, ease: 'back.out' }, 0)
      .to(group.scale, { x: sceneScale[0], y: sceneScale[1], z: sceneScale[2], duration: 0.2, ease: 'back.out' }, 0.12)
      .to(pressAmount, { value: 0.0, duration: 0.2, ease: 'back.out' }, 0.12);

    if (group.userData.emit) {
      group.userData.emit('hub-collection.select', { source: 'hub-collection-badge' });
    }
  };

  group.userData.handlers = {
    onPointerOver: onHoverIn,
    onPointerOut: onHoverOut,
    onClick: onClick,
  };

  group.userData.cleanup = () => {
    if (hoverTween) hoverTween.kill();
    if (pressTween) pressTween.kill();
    geometry.dispose();
    material.dispose();
    if (map) map.dispose();
  };

  return group;
}
